import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from "expo-audio";

// Generated by scripts/make-sounds.py.
import endWav from "../../../assets/sounds/end.wav";
import startWav from "../../../assets/sounds/start.wav";

export type Beep = "start" | "end";

const sources = { start: startWav, end: endWav };

const players: Partial<Record<Beep, AudioPlayer>> = {};

// expo-audio plays through silent mode by default; a muted phone stays quiet (iOS), and the beeps
// mix with whatever music is on.
const ready = setAudioModeAsync({
  playsInSilentMode: false,
  interruptionMode: "mixWithOthers",
}).catch(() => {});

// A short beep at the start and end of a work timer and the end of a rest. Audio that cannot be
// set up (web without a user gesture, a missing native module) is dropped: the bar still shows.
export function beep(kind: Beep) {
  ready.then(() => {
    try {
      const player = (players[kind] ??= createAudioPlayer(sources[kind]));
      player.seekTo(0);
      player.play();
    } catch {}
  });
}
